{
  "issues": [],
  "actions": [
    {
      "id": "A1",
      "status": "performed",
      "summary": "陆照临全程站在山门石阶原地，未向伤者方向移动。",
      "paragraphId": "P1"
    },
    {
      "id": "A2",
      "status": "performed",
      "summary": "陆照临向守门弟子说出了“老人让我来问山门的灯”。",
      "paragraphId": "P2"
    },
    {
      "id": "A3",
      "status": "performed",
      "summary": "陆照临只说了这一句，未追加解释、追问或交出文书。",
      "paragraphId": "P2"
    },
    {
      "id": "A4",
      "status": "performed",
      "summary": "说完后收声停在原地等待，未替玩家决定下一步。",
      "paragraphId": "P3"
    },
    {
      "id": "A5",
      "status": "performed",
      "summary": "陆照临未靠近伤者，与伤者保持原有距离。",
      "paragraphId": "P3"
    },
    {
      "id": "A6",
      "status": "performed",
      "summary": "陆照临未触碰或移动引荐文书、空灯等任何物品。",
      "paragraphId": "P3"
    }
  ],
