{
  "events": [
    {
      "id": "O1",
      "paragraphId": "P1",
      "actor": "character_ae4cb42b9b49",
      "mode": "actual",
      "summary": "陆照临仍站在封山青石前的湿石阶上，雨继续下。",
      "changes": [
        {
          "entityId": "character_ae4cb42b9b49",
          "attribute": "locationId",
          "value": "location_open_gate"
        }
      ],
      "introduced": [],
      "usedItemIds": []
    },
    {
      "id": "O2",
      "paragraphId": "P2",
      "actor": "character_ae4cb42b9b49",
      "mode": "actual",
      "summary": "陆照临将怀中的引荐文书往里按平，确认它妥帖收在衣内，手抽出后衣襟合拢。",
      "changes": [
        {
          "entityId": "item_open_letter",
          "attribute": "ownerCharacterId",
          "value": "character_ae4cb42b9b49"
        }
      ],
      "introduced": [],
      "usedItemIds": [
        "item_open_letter"
      ]
    },
    {
      "id": "O3",
      "paragraphId": "P3",
      "actor": "character_ae4cb42b9b49",
      "mode": "actual",
      "summary": "陆照临没有把引荐文书递给任何人。",
      "changes": [],
      "introduced": [],
      "usedItemIds": []
    },
    {
      "id": "O4",
      "paragraphId": "P4",
      "actor": "character_ae4cb42b9b49",
      "mode": "actual",
      "summary": "守门弟子没有动静，陆照临也没有再看过去，手垂回身侧，人仍立在原处。",
      "changes": [
        {
          "entityId": "character_ae4cb42b9b49",
          "attribute": "locationId",
          "value": "location_open_gate"
        }
      ],
      "introduced": [],
      "usedItemIds": []
    }
  ]
}

